namespace fs=std::filesystem;
void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
template<class E=std::exception,class F>void rejects(F f){bool caught=false;try{f();}catch(const E&){caught=true;}check(caught,"Expected native normalization refusal");}
void write(const fs::path& p,const std::string& s){std::ofstream out(p,std::ios::binary);out<<s;out.close();check(bool(out),"Write authored fixture");}
std::shared_ptr<const ExpressionMatrixSource> fixture(const fs::path& root,const std::string& name,std::size_t features,std::size_t observations,const std::string& entries,std::size_t n){
    const auto folder=root/name;fs::create_directory(folder);std::ostringstream f,o;f<<"feature_id\n";o<<"observation_id\n";for(std::size_t i=0;i<features;++i)f<<'G'<<i<<'\n';for(std::size_t i=0;i<observations;++i)o<<'O'<<i<<'\n';write(folder/"features.tsv",f.str());write(folder/"observations.tsv",o.str());write(folder/"matrix.mtx","%%MatrixMarket matrix coordinate integer general\n"+std::to_string(features)+" "+std::to_string(observations)+" "+std::to_string(n)+"\n"+entries);const auto r=import_expression_matrix((folder/"matrix.mtx").u8string(),(folder/"features.tsv").u8string(),(folder/"observations.tsv").u8string(),(folder/"source.qmx").u8string());return open_expression_matrix(r.path,r.file_sha256);
}
class ObservedMatrix final:public ExpressionMatrixSource {
    std::shared_ptr<const ExpressionMatrixSource> source_;
public:
    mutable std::size_t reads=0,max_features=0;std::atomic<bool>* cancel_after_read=nullptr;
    explicit ObservedMatrix(std::shared_ptr<const ExpressionMatrixSource> source):source_(std::move(source)){}
    const ExpressionMatrixMetadata& metadata()const override{return source_->metadata();}
    const std::string& path()const override{return source_->path();}
    const std::string& file_sha256()const override{return source_->file_sha256();}
    std::size_t payload_bytes()const override{return source_->payload_bytes()+sizeof(*this);}
    void require_current(const std::atomic<bool>* c)const override{source_->require_current(c);}
    std::vector<ExpressionFeature> feature_page(std::uint64_t first,std::size_t n,std::size_t w,const std::atomic<bool>* c)const override{return source_->feature_page(first,n,w,c);}
    ExpressionFeaturePage search_features(const std::string& q,std::uint64_t o,std::size_t n,std::size_t w,const std::atomic<bool>* c)const override{return source_->search_features(q,o,n,w,c);}
    std::vector<std::string> observation_page(std::uint64_t first,std::size_t n,std::size_t w,const std::atomic<bool>* c)const override{return source_->observation_page(first,n,w,c);}
    std::optional<std::uint64_t> feature_index(const std::string& id,const std::atomic<bool>* c)const override{return source_->feature_index(id,c);}
    std::optional<std::uint64_t> observation_index(const std::string& id,const std::atomic<bool>* c)const override{return source_->observation_index(id,c);}
    std::vector<std::uint64_t> observation_indices(const std::vector<std::string>& ids,std::size_t w,const std::atomic<bool>* c)const override{return source_->observation_indices(ids,w,c);}
    ExpressionSparseBlock read(const ExpressionMatrixSelection& selection,std::size_t w,const std::atomic<bool>* c)const override{auto result=source_->read(selection,w,c);++reads;max_features=std::max(max_features,selection.features.size());if(cancel_after_read)cancel_after_read->store(true);return result;}
};
void exercise(const fs::path& root){
    auto parent=fixture(root,"analytical",4,5,"1 1 1\n1 2 0\n1 4 2\n2 1 3\n2 2 4\n2 4 2\n3 2 6\n3 5 1\n4 1 6\n4 5 3\n",10);auto observed=std::make_shared<ObservedMatrix>(parent);
    ExpressionQcOptions options;options.groups={{"mito 伪",{0,2}},{"overlap",{1,2}}};auto qc=expression_qc(observed,options);
    check(qc->features()==4 && qc->totals()==std::vector<std::uint64_t>{10,10,0,4,4} && qc->detected_features()==std::vector<std::uint64_t>{3,2,0,2,2},"Full-source QC totals/detected/zero libraries differ");
    check(qc->group_totals()==std::vector<std::uint64_t>{1,6,0,2,1,3,10,0,2,1} && qc->group_fraction(0,0)==.1 && !qc->group_fraction(0,2),"Explicit overlapping group totals/zero fractions differ");check(qc->peak_work_bytes()<=options.work_bytes && observed->reads==qc->batches() && observed->max_features==4,"QC must batch full features within its reservation");
    const auto unchanged=parent->read({{0,1,2,3},{}});const auto normal=normalize_expression(observed,qc,{100,false});const auto logged=normalize_expression(observed,qc,{100,true});check(observed->reads==qc->batches() && normal.qc()==logged.qc(),"Parameter changes repeated full QC");
    const auto block=normal.source()->read({{0},{}});check(block.counts.empty() && block.domain==ExpressionValueDomain::Continuous && block.continuous==std::vector<double>{10,0,50} && block.observation_indices==std::vector<std::uint64_t>{0,1,3},"Selected gene used its own projection as library denominator");
    const auto logarithms=logged.source()->read({{0},{}});for(std::size_t i=0;i<block.continuous.size();++i)check(std::abs(logarithms.continuous[i]-std::log1p(block.continuous[i]))<1e-14,"Native log1p values differ");
    check(parent->read({{0,1,2,3},{}}).sha256==unchanged.sha256 && normal.source()->path().empty() && normal.source()->file_sha256().empty(),"Normalization changed raw counts or masquerades as a raw file");
    check(normal.source()->metadata().source_sha256!=logged.source()->metadata().source_sha256 && normal.source()->feature_page(0,1)[0].sha256!=parent->feature_page(0,1)[0].sha256,"Derived parameters/feature identity alias raw");
    auto replay=replay_expression_normalization(parent,normal.recipe());check(replay.qc()->sha256()==qc->sha256() && replay.source()->read({{0},{}}).sha256==block.sha256,"Native recipe replay differs");auto corrupt=normal.recipe();corrupt[40]^=1;rejects([&]{replay_expression_normalization(parent,corrupt);});rejects([&]{expression_qc(logged.source());});rejects([&]{normalize_expression(parent,qc,{0,false});});
    auto duplicate=options;duplicate.groups[0].features={0,0};rejects([&]{expression_qc(parent,duplicate);});duplicate=options;duplicate.groups[1].name=duplicate.groups[0].name;rejects([&]{expression_qc(parent,duplicate);});auto out_of_range=options;out_of_range.groups[0].features={4};rejects([&]{expression_qc(parent,out_of_range);});
    auto bounded=options;bounded.work_bytes=8u*1024*1024;check(expression_qc(parent,bounded)->sha256()==qc->sha256(),"QC work reservation changed scientific identity");rejects<WorkflowCaptureLimit>([&]{normal.source()->read({{0},{}},8u*1024*1024);});
    CoordinateFrame frame;frame.id="image";frame.source_id="authored-image";frame.unit=CoordinateUnit::Pixel;frame.image_level_zero=true;frame.width=frame.height=8;
    std::vector<ExpressionObservation> rows;for(std::size_t i=0;i<5;++i)rows.push_back({0,"O"+std::to_string(i),{double(i),2}});auto spatial=ExpressionMatrixSpatialSnapshot::create(normal.source(),rows,frame);auto values=spatial.dataset({0});check(values.continuous()==std::vector<double>{10,0,0,50,0} && values.valid()==std::vector<std::uint8_t>{1,1,1,1,1},"Normalized projection changed measured sparse zeros to missing");const auto display=gene_display_field(GeneDisplayRequest(values,"G0"));check(display->legend.zeros==3 && display->legend.missing==0,"Native gene display does not consume derived values");
    Project project;const auto image=project.add_document(std::make_shared<Document>(dense_image_server(Image::demo())));keep_expression_matrix(project,image,parent);const auto id=keep_expression_normalization(project,image,normal);rejects<WorkflowOutputExists>([&]{keep_expression_normalization(project,image,normal);});rejects([&]{keep_expression_matrix(project,image,normal.source());});
    check(expression_normalization_ids(project,image,parent->metadata().source_sha256)==std::vector<std::string>{id},"Saved recipe parent filter differs");
    GeneViewSession session(256u*1024*1024);session.bind(ExpressionMatrixSpatialSnapshot::create(parent,rows,frame));auto view=session.options();view.enabled=true;view.genes={"G0","G1"};session.configure(view);session.wait();check(session.result() && session.error().empty(),"Raw native gene session failed");
    const auto original_positions=session.dataset()->observations();session.request_qc(options);session.wait();const auto cached_qc=session.qc_result();check(cached_qc && cached_qc->sha256()==qc->sha256(),"Gene worker full-source QC differs");
    session.normalize({100,false});session.wait();check(session.result() && session.qc_result()==cached_qc && session.dataset()->continuous()==std::vector<double>{10,0,0,50,0},"Gene worker normalization/projection differs or recomputed QC");const auto normalized_source=session.normalization_result()->source();
    view=session.options();view.display.opacity=.5;session.configure(view);session.wait();check(session.normalization_result()->source()==normalized_source && session.qc_result()==cached_qc,"Display changes rebuilt normalized source/QC");
    session.normalize({200,false});session.wait();check(session.result() && session.qc_result()==cached_qc && session.dataset()->continuous()==std::vector<double>{20,0,0,100,0},"Target change recomputed QC or altered denominator");session.normalize({100,true});session.wait();check(session.result() && session.qc_result()==cached_qc,"Log mode did not reuse QC");view=session.options();view.display.transform=GeneDisplayTransform::Log1p;rejects<std::invalid_argument>([&]{session.configure(view);});
    for(std::size_t i=0;i<original_positions.size();++i)check(session.dataset()->observations()[i].id==original_positions[i].id && session.dataset()->observations()[i].position.x==original_positions[i].position.x && session.dataset()->observations()[i].position.y==original_positions[i].position.y,"Derived view moved scientific coordinates/IDs");
    session.raw_values();session.wait();check(session.result() && session.dataset()->counts()==std::vector<std::uint64_t>{1,0,0,2,0} && session.qc_result()==cached_qc,"Raw switch changed counts or discarded valid QC");session.restore_normalization(normal.recipe());session.wait();check(session.result() && session.qc_result()==cached_qc && session.normalization_result()->recipe()==normal.recipe(),"Saved recipe did not reuse compatible verified QC");session.clear();session.bind(values);rejects<std::invalid_argument>([&]{session.normalize();});
    project.save_new((root/"study.qpx").u8string());auto saved=Project::open((root/"study.qpx").u8string());auto request=expression_normalization_open_request(*saved,image,id);auto restored=request.open();check(restored.recipe()==normal.recipe() && restored.source()->read({{0},{}}).sha256==block.sha256,"Saved normalization native replay differs");remove_expression_normalization(*saved,image,id);check(expression_normalization_ids(*saved,image).empty(),"Remove normalization failed");saved->document(image)->undo();check(expression_normalization_ids(*saved,image)==std::vector<std::string>{id},"Normalization removal is not undoable");
    auto huge=fixture(root,"exact",2,1,"1 1 9007199254740993\n2 1 1\n",2);auto exact=expression_qc(huge);check(exact->totals()[0]==9007199254740994ULL && huge->read({{0},{}}).counts[0]==9007199254740993ULL,"QC converted raw uint64 to double");rejects([&]{normalize_expression(huge,qc);});rejects([&]{replay_expression_normalization(huge,normal.recipe());});
    auto overflow=fixture(root,"overflow",2,1,"1 1 18446744073709551615\n2 1 1\n",2);rejects<std::overflow_error>([&]{expression_qc(overflow);});
    auto wide=fixture(root,"wide",1200,1,"1200 1 3\n",1);ExpressionQcOptions groups;ExpressionFeatureGroup all;all.name="all genes 尾";for(std::size_t i=0;i<1200;++i)all.features.push_back(i);groups.groups={all};auto wide_qc=expression_qc(wide,groups);auto wide_normal=normalize_expression(wide,wide_qc);check(wide_qc->batches()>1 && wide_qc->totals()[0]==3 && wide_normal.recipe().size()>4096,"Wide fixture did not exercise batches/record chunking");keep_expression_matrix(*saved,image,wide);const auto wide_id=keep_expression_normalization(*saved,image,wide_normal);saved->save_new((root/"wide.qpx").u8string());auto wide_saved=Project::open((root/"wide.qpx").u8string());check(expression_normalization_open_request(*wide_saved,image,wide_id).open().recipe()==wide_normal.recipe(),"Chunked Unicode-group recipe did not persist/replay");
    session.clear();session.bind(ExpressionMatrixSpatialSnapshot::create(wide,{{0,"O0",{1,1}}},frame));session.normalize();session.poll();session.cancel();session.wait();check(!session.result() && !session.qc_result(),"Cancelled QC generation published a late result");
    std::atomic<bool> cancel{false};auto interrupt=std::make_shared<ObservedMatrix>(wide);interrupt->cancel_after_read=&cancel;rejects<WorkflowCancelled>([&]{expression_qc(interrupt,{},&cancel);});check(interrupt->reads==1,"Cancellation did not stop between real sparse batches");
    write(fs::path(parent->path()+"-wal"),"unreviewed writer");rejects<WorkflowInputChanged>([&]{normal.source()->read({{0},{}});});fs::remove(fs::u8path(parent->path()+"-wal"));{std::ofstream changed(fs::u8path(parent->path()),std::ios::binary|std::ios::app);changed.put('x');}rejects<WorkflowInputChanged>([&]{normal.source()->require_current();});rejects<WorkflowInputChanged>([&]{request.open();});
}
void real(const std::string& matrix,const fs::path& oracle,const fs::path& output){
    fs::create_directories(output);std::ifstream in(oracle);std::string key,matrix_sha,file_sha,line;std::uint64_t features=0,observations=0;in>>key>>matrix_sha;check(key=="source_matrix_sha256","Oracle source identity header");in>>key>>file_sha;check(key=="store_sha256","Oracle store identity header");in>>key>>features;check(key=="features","Oracle feature universe header");in>>key>>observations;check(key=="observations","Oracle observation universe header");std::getline(in,line);std::getline(in,line);check(line=="index\ttotal\tdetected\tgroup","Oracle exact columns");
    auto source=open_expression_matrix(matrix,file_sha);check(source->metadata().features==32285 && source->metadata().features==features && source->metadata().observations==2702 && source->metadata().observations==observations && source->metadata().input_sha256[0]==matrix_sha,"Full real source/feature universe differs");ExpressionQcOptions options;options.groups={{"first-and-last",{0,features-1}}};const auto start=std::chrono::steady_clock::now();auto qc=expression_qc(source,options);const auto elapsed=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();
    for(std::uint64_t i=0;i<observations;++i){std::uint64_t index,total,detected,group;check(bool(in>>index>>total>>detected>>group) && index==i,"Oracle observation axis truncated/reordered");check(qc->totals()[i]==total && qc->detected_features()[i]==detected && qc->group_totals()[i]==group,"Full real QC differs from independent original Matrix Market sums/detection");}in>>std::ws;check(in.eof(),"Oracle has surplus observations");
    auto normalized=normalize_expression(source,qc);const auto raw=source->read({{0,features-1},{}}),derived=normalized.source()->read({{0,features-1},{}});check(raw.observation_indices==derived.observation_indices && raw.offsets==derived.offsets,"Real derived sparse geometry/axes differ");for(std::size_t i=0;i<raw.counts.size();++i){const auto total=qc->totals()[raw.observation_indices[i]];const auto expected=total?std::log1p((double(raw.counts[i])*10000)/double(total)):0;check(std::abs(expected-derived.continuous[i])<1e-12,"Real normalized/log values differ");}
    Project project;const auto image=project.add_document(std::make_shared<Document>(dense_image_server(Image::demo())));keep_expression_matrix(project,image,source);const auto id=keep_expression_normalization(project,image,normalized);project.save_new((output/"study.qpx").u8string());auto saved=Project::open((output/"study.qpx").u8string());auto replay=expression_normalization_open_request(*saved,image,id).open(64u*1024*1024);check(replay.qc()->sha256()==qc->sha256() && replay.qc()->batches()!=qc->batches() && replay.source()->read({{0,features-1},{}}).sha256==derived.sha256,"Real project replay/work-batch change differs");
    std::ofstream report(output/"real.json");report<<"{\"features\":"<<features<<",\"observations\":"<<observations<<",\"batches\":"<<qc->batches()<<",\"replay_batches\":"<<replay.qc()->batches()<<",\"work_reservation\":"<<qc->peak_work_bytes()<<",\"qc_ms\":"<<elapsed<<",\"qc_sha256\":\""<<qc->sha256()<<"\",\"normalization_sha256\":\""<<id<<"\",\"independent_all_observations_equal\":true}\n";report.close();check(bool(report),"Write real QC receipt");std::cout<<"Full real QC: "<<features<<" features / "<<observations<<" observations; all totals/detected/group values match original Matrix Market oracle; "<<qc->batches()<<"/"<<replay.qc()->batches()<<" batches, saved exact recipe/QC replay, "<<elapsed<<"ms (host-local, no comparison claim)\n";
}
int main(int argc,char** argv){try{if(!has_expression_matrix_storage()){std::cout<<"Native matrix storage disabled\n";return 0;}const auto root=fs::current_path()/("normalization-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));fs::create_directory(root);exercise(root);if(argc==4)real(argv[1],fs::u8path(argv[2]),fs::u8path(argv[3]));std::cout<<"Native full-universe QC/normalization: exact counts/groups/zeros, derived sparse values, bounded batches/cancel/stale, project persistence/replay and native gene projection pass\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
